function App() {
  const [ready, setReady] = useState(false);
  useEffect(() => {
    const t = setTimeout(() => setReady(true), 900);
    return () => clearTimeout(t);
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>Product page</h3>
      <p><b>Title + price</b> (shell) — painted immediately.</p>
      <div style={{ marginTop: 12, padding: 12, border: '1px solid #ddd', borderRadius: 8 }}>
        <b>Reviews (slow boundary)</b>
        {ready
          ? <p>Streamed in: 128 reviews loaded.</p>
          : <p style={{ opacity: 0.5 }}>Loading reviews… (skeleton fallback)</p>}
      </div>
    </div>
  );
}

