function App() {
  // Fix: fetch inside the suspended child.
  const code = [
    "export default function Page() {       // not async anymore",
    "  return (",
    "    <>",
    "      <Header />",
    "      <Suspense fallback={<Skeleton/>}>",
    "        <Reviews />                    // async component",
    "      </Suspense>",
    "    </>",
    "  );",
    "}",
    "async function Reviews() {",
    "  const reviews = await getReviews(); // await is INSIDE the boundary",
    "  return <ReviewList data={reviews} />;",
    "}",
  ];
  return (<pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>{code.join('\n')}</pre>);
}

// app/product/page.tsx (Server Component)
import { Suspense } from 'react';

export default function Page() {
  return (
    <>
      <Header />
      <Suspense fallback={<ReviewsSkeleton />}>
        {/* Reviews awaits its own data INSIDE the boundary */}
        <Reviews />
      </Suspense>
    </>
  );
}

async function Reviews() {
  const reviews = await getReviews(); // slow call, scoped to the boundary
  return <ReviewList data={reviews} />;
}
